/* Admin panel markup — index.html'den DOĞRU sınırla ayrıştırıldı (script-maskeli sayım).
   İçindeki inline scriptler innerHTML ile çalışmayacağından bu dosyada KOD olarak taşınır. */
window.__INS_ADMIN_HTML="\n  <div class=\"adm-login\">\n    <div class=\"card\">\n      <div class=\"lg\"><span class=\"mark\">M</span>Meridyen Yönetim</div>\n      <p>Firma yönetici paneline giriş yapın.</p>\n      <div class=\"err\" id=\"admErr\">Hatalı şifre. Tekrar deneyin.</div>\n      <input type=\"text\" id=\"admUser\" placeholder=\"Kullanıcı adı\" value=\"\" autocomplete=\"off\">\n      <input type=\"password\" id=\"advPwd\" placeholder=\"Şifre\" onkeydown=\"if(event.key==='Enter')admLogin()\">\n      <button class=\"btn btn-primary\" style=\"width:100%;justify-content:center\" onclick=\"admLogin()\">Giriş Yap</button>\n      <div class=\"hint\">Yetkili girişi · Şifrenizi bilmiyorsanız sistem yöneticinizle görüşün.</div>\n      <div class=\"hint\"><a href=\"#\" onclick=\"closeAdmin();return false\" style=\"color:var(--accent)\">← Siteye dön</a></div>\n    </div>\n  </div>\n  <div class=\"adm-dash\">\n    <div class=\"adm-side\">\n      <div class=\"lg\"><span class=\"mark\">M</span>Meridyen</div>\n      <button onclick=\"openOnboarding()\" style=\"background:var(--accent);color:var(--on-accent);font-weight:700;border:none\">🪄 Kurulum Sihirbazı</button>\n      <button class=\"on\" data-pane=\"dash\" onclick=\"admNav('dash',this)\">📊 Genel Bakış</button>\n      <button data-pane=\"content\" onclick=\"admNav('content',this)\">✏️ Site İçeriği</button>\n      <button data-pane=\"icstudio\" onclick=\"admNav('icstudio',this)\" style=\"background:linear-gradient(135deg,#0891b2,#22d3ee);color:#fff;font-weight:700;border:none\">✨ İçerik Stüdyosu</button>\n      <button data-pane=\"proxai\" onclick=\"admNav('proxai',this)\">🔌 ProX API & Motorlar</button>\n      <button data-pane=\"brand\" onclick=\"admNav('brand',this)\">🖼️ Marka & Logo</button>\n      <button data-pane=\"menutext\" onclick=\"admNav('menutext',this)\">🔤 Menü & Footer Yazıları</button>\n      <button data-pane=\"ads\" onclick=\"admNav('ads',this)\">🔌 Google & Reklam</button>\n      <button data-pane=\"diller\" onclick=\"admNav('diller',this)\">🌐 Diller & İçerik (TR/EN)</button>\n      <button data-pane=\"iletisim\" onclick=\"admNav('iletisim',this)\">📞 İletişim Sayfası & Konum</button>\n      <button data-pane=\"faq\" onclick=\"admNav('faq',this)\">❓ İnşaat Soru-Cevap</button>\n      <button data-pane=\"social\" onclick=\"admNav('social',this)\">🔗 Sosyal & İlan Linkleri</button>\n      <button data-pane=\"stats\" onclick=\"admNav('stats',this)\">📊 İstatistik & Sertifika</button>\n      <button data-pane=\"projects\" onclick=\"admNav('projects',this)\">🏗️ Projeler</button>\n      <button data-pane=\"services\" onclick=\"admNav('services',this)\">🧰 Hizmetler</button>\n      <button data-pane=\"arsa\" onclick=\"admNav('arsa',this)\">🤝 Kat Karşılığı Hesap</button>\n      <button data-pane=\"ilanlar\" onclick=\"admNav('ilanlar',this)\">🏘️ İlanlar (EİDS)</button>\n      <button data-pane=\"portfoy\" onclick=\"admNav('portfoy',this)\">🔒 Özel Portföy (ProX)</button>\n      <button data-pane=\"proje3d\" onclick=\"admNav('proje3d',this)\">🏗️ 3D Proje Üretici (Kat Karşılığı)</button>\n      <button data-pane=\"dwgproje\" onclick=\"admNav('dwgproje',this)\">📐 DWG Mimari Proje</button>\n      <button data-pane=\"contracts\" onclick=\"admNav('contracts',this)\">📋 Sözleşmeler</button>\n      <button data-pane=\"leads\" onclick=\"admNav('leads',this)\">👥 Müşteriler / Teklifler</button>\n      <button data-pane=\"gorusmeler\" onclick=\"admNav('gorusmeler',this)\">💬 Görüşmeler & Teklifler (ProX)</button>\n      <button data-pane=\"theme\" onclick=\"admNav('theme',this)\">🎨 Tema & Renk</button>\n      <button data-pane=\"settings\" onclick=\"admNav('settings',this)\">⚙️ Ayarlar & Güvenlik</button>\n      <div class=\"sp\"></div>\n      <button onclick=\"closeAdmin()\">🌐 Siteyi Görüntüle</button>\n      <button onclick=\"admLogout()\">🚪 Çıkış Yap</button>\n    </div>\n    <div class=\"adm-main\">\n      <div class=\"adm-pane on\" id=\"pane-dash\">\n        <h2>Genel Bakış</h2><div class=\"crumb\">Hoş geldiniz, Yönetici · Meridyen Yapı</div>\n        <div class=\"kpi\" id=\"kpi\"></div>\n        <div class=\"panelcard\"><h3>Son Teklif Talepleri</h3><div id=\"dashLeads\"></div></div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-content\">\n        <h2>Site İçeriği</h2><div class=\"crumb\">Ana sayfa metinleri ve marka bilgileri</div>\n        <div class=\"panelcard\">\n          <label>Firma Adı</label><input type=\"text\" id=\"a_brand\" value=\"Meridyen Yapı\">\n          <label>Telefon</label><input type=\"text\" id=\"a_tel\" value=\"+90 212 000 00 00\">\n          <label>Hero Başlığı</label><textarea id=\"a_h1\" rows=\"2\">Şehrin silüetini güvenle yeniden inşa ediyoruz</textarea>\n          <label>Hero Alt Metni</label><textarea id=\"a_sub\" rows=\"2\">Konut, ticari ve karma projelerde anahtar teslim mühendislik; kentsel dönüşüm, kat karşılığı ve tadilat hizmetlerinde 40 yıllık güven.</textarea>\n          <label>Hakkımızda Metni</label><textarea id=\"a_about\" rows=\"4\">Meridyen Yapı; 1986'da temellerini attığı kurumsal kültürünü üç kuşaktır aynı titizlikle sürdüren bir yapı ve gayrimenkul geliştirme şirketidir. Arsa analizinden anahtar teslime kadar her aşamayı kendi mühendis kadromuzla yönetir; deprem güvenliği, malzeme kalitesi ve teslim takvimini taviz verilmez ilkeler olarak görürüz.</textarea>\n          <button class=\"btn btn-primary\" style=\"margin-top:16px\" onclick=\"saveContent()\">Değişiklikleri Kaydet</button>\n        </div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-icstudio\"><div id=\"csHost\"></div></div>\n      <div class=\"adm-pane\" id=\"pane-proxai\">\n        <h2>ProX API & ProX Motorları · İki Bağımsız Ajan</h2><div class=\"crumb\">İki ayrı yapay zekâ: <b>İçerik Ajanı</b> (admin makale/haber üretimi) ve <b>Site Asistanı</b> (ziyaretçi sohbeti). Her birinin KENDİ sağlayıcı, anahtar, prompt ve yetenekleri vardır. Anahtarlar yalnızca bu tarayıcıda saklanır.</div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin:0 0 4px\">✨ İçerik Ajanı — Makale & Haber Üretimi</h3>\n          <p style=\"font-size:12.5px;color:#888;margin:0 0 10px\">İçerik Stüdyosu'nu çalıştırır (SEO makale + günlük otomatik haber).</p>\n          <label>Sağlayıcı</label>\n          <select id=\"cxci_provider\"><option value=\"auto\">Otomatik (anahtarı olanı kullan)</option><option value=\"prox\">ProX</option><option value=\"m1\">Motor-1</option><option value=\"m2\">Motor-2</option><option value=\"m3\">Motor-3</option></select>\n          <label>ProX API Anahtarı</label><input type=\"password\" id=\"cxci_prox\" placeholder=\"ProX kiracı anahtarı\" autocomplete=\"off\">\n          <label>Motor-1 anahtarı</label><input type=\"password\" id=\"cxci_ds\" placeholder=\"sk-...\" autocomplete=\"off\">\n          <label>Motor-2 anahtarı</label><input type=\"password\" id=\"cxci_oa\" placeholder=\"sk-...\" autocomplete=\"off\">\n          <label>Motor-3 anahtarı</label><input type=\"password\" id=\"cxci_cl\" placeholder=\"anahtar\" autocomplete=\"off\">\n          <label>Görsel servisi <span style=\"opacity:.6;font-weight:400\">(opsiyonel — boşsa Openverse ücretsiz görsel)</span></label><input type=\"password\" id=\"cxci_pex\" placeholder=\"Görsel servisi anahtarı\" autocomplete=\"off\">\n          <label>İçerik promptu / editöryal ton <span style=\"opacity:.6;font-weight:400\">(opsiyonel)</span></label><textarea id=\"cxci_sys\" rows=\"2\" placeholder=\"Örn. kurumsal, güven veren; SEO uyumlu; uydurma rakam/garanti verme.\"></textarea>\n          <div style=\"display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:14px\"><button class=\"btn btn-primary\" onclick=\"insContentSave()\">Kaydet</button><button class=\"btn\" onclick=\"insContentTest()\">Bağlan & Test</button><span id=\"cxci_status\" style=\"opacity:.75;font-size:13px\"></span></div>\n        </div>\n        <div class=\"panelcard\" style=\"margin-top:16px\">\n          <h3 style=\"margin:0 0 4px\">💬 Site Asistanı — Ziyaretçi Sohbeti</h3>\n          <p style=\"font-size:12.5px;color:#888;margin:0 0 10px\">Sitedeki ProX Asistan sohbetini çalıştırır. İçerik Ajanı'ndan tamamen ayrıdır.</p>\n          <label>Sağlayıcı</label>\n          <select id=\"cxsi_provider\"><option value=\"auto\">Otomatik (anahtarı olanı kullan)</option><option value=\"prox\">ProX</option><option value=\"m1\">Motor-1</option><option value=\"m2\">Motor-2</option><option value=\"m3\">Motor-3</option></select>\n          <label>ProX API Anahtarı</label><input type=\"password\" id=\"cxsi_prox\" placeholder=\"ProX kiracı anahtarı\" autocomplete=\"off\">\n          <label>Motor-1 anahtarı</label><input type=\"password\" id=\"cxsi_ds\" placeholder=\"sk-...\" autocomplete=\"off\">\n          <label>Motor-2 anahtarı</label><input type=\"password\" id=\"cxsi_oa\" placeholder=\"sk-...\" autocomplete=\"off\">\n          <label>Motor-3 anahtarı</label><input type=\"password\" id=\"cxsi_cl\" placeholder=\"anahtar\" autocomplete=\"off\">\n          <label>Asistan promptu / ton <span style=\"opacity:.6;font-weight:400\">(opsiyonel — kuruma özel ek)</span></label><textarea id=\"cxsi_sys\" rows=\"2\" placeholder=\"Örn. sıcak ama profesyonel; önce ihtiyacı anla, sonra keşfe/temsilciye yönlendir.\"></textarea>\n          <label>Yetenekler</label>\n          <div style=\"display:flex;flex-wrap:wrap;gap:12px;font-size:13px;margin-top:4px\">\n            <label style=\"display:flex;gap:6px;align-items:center\"><input type=\"checkbox\" id=\"cxsi_cap_phone\" checked> 📞 Telefon iste (canlı danışman araması)</label>\n            <label style=\"display:flex;gap:6px;align-items:center\"><input type=\"checkbox\" id=\"cxsi_cap_lead\" checked> 🎯 Lead nitelendirme</label>\n            <label style=\"display:flex;gap:6px;align-items:center\"><input type=\"checkbox\" id=\"cxsi_cap_advice\" checked> 💡 Bölge & fiyat danışmanlığı</label>\n            <label style=\"display:flex;gap:6px;align-items:center\"><input type=\"checkbox\" id=\"cxsi_cap_match\" checked> 🔑 Proje/ilan eşleştirme</label>\n            <label style=\"display:flex;gap:6px;align-items:center\"><input type=\"checkbox\" id=\"cxsi_cap_multilang\" checked> 🌐 Çok dilli</label>\n          </div>\n          <div style=\"display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:14px\"><button class=\"btn btn-primary\" onclick=\"insSiteSave()\">Kaydet</button><button class=\"btn\" onclick=\"insSiteTest()\">Bağlan & Test</button><span id=\"cxsi_status\" style=\"opacity:.75;font-size:13px\"></span></div>\n        </div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-brand\">\n        <h2>Marka & Logo</h2><div class=\"crumb\">Logoyu bilgisayarınızdan yükleyin — üst menü, alt menü ve tüm sayfalara uygulanır. \"Yayınla\" ile kaydedilir ve neden-biz dâhil her sayfaya işlenir.</div>\n        <div class=\"panelcard\">\n          <label>Üst Menü Logosu (header)</label>\n          <div style=\"display:flex;gap:16px;align-items:center;margin:8px 0 4px\">\n            <div id=\"bp_logo\" style=\"width:56px;height:56px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:grid;place-items:center;color:#fff;font-weight:800;font-size:24px;overflow:hidden;flex-shrink:0\">M</div>\n            <div style=\"flex:1\"><input type=\"file\" id=\"f_logo\" accept=\"image/*\" onchange=\"brandUpload(this,'logo')\"><div style=\"font-size:12px;color:#888;margin-top:4px\">PNG/SVG · şeffaf zemin önerilir · <a href=\"#\" onclick=\"brandClear('logo');return false\" style=\"color:var(--accent)\">kaldır (M harfine dön)</a></div></div>\n          </div>\n          <label style=\"margin-top:16px;display:block\">Alt Menü Logosu (footer) — boş bırakılırsa üst logo kullanılır</label>\n          <div style=\"display:flex;gap:16px;align-items:center;margin:8px 0 4px\">\n            <div id=\"bp_logoFooter\" style=\"width:64px;height:44px;border-radius:10px;background:#14161c;display:grid;place-items:center;color:#9aa0ab;font-size:12px;overflow:hidden;flex-shrink:0\">—</div>\n            <div style=\"flex:1\"><input type=\"file\" id=\"f_logoFooter\" accept=\"image/*\" onchange=\"brandUpload(this,'logoFooter')\"><div style=\"font-size:12px;color:#888;margin-top:4px\"><a href=\"#\" onclick=\"brandClear('logoFooter');return false\" style=\"color:var(--accent)\">kaldır</a></div></div>\n          </div>\n          <label style=\"margin-top:16px;display:block\">Favicon (tarayıcı sekme ikonu)</label>\n          <div style=\"display:flex;gap:16px;align-items:center;margin:8px 0 4px\">\n            <div id=\"bp_favicon\" style=\"width:36px;height:36px;border-radius:8px;background:#14161c;display:grid;place-items:center;color:#9aa0ab;font-size:16px;overflow:hidden;flex-shrink:0\">★</div>\n            <div style=\"flex:1\"><input type=\"file\" id=\"f_favicon\" accept=\"image/*\" onchange=\"brandUpload(this,'favicon')\"><div style=\"font-size:12px;color:#888;margin-top:4px\"><a href=\"#\" onclick=\"brandClear('favicon');return false\" style=\"color:var(--accent)\">kaldır</a></div></div>\n          </div>\n          <label style=\"margin-top:16px;display:block\">Marka Adı (yazı — logo yanında/altında)</label>\n          <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px\"><input type=\"text\" id=\"b_name\" placeholder=\"Meridyen\" oninput=\"BRAND.name=this.value;applyBrand()\"><input type=\"text\" id=\"b_name2\" placeholder=\" Yapı\" oninput=\"BRAND.name2=this.value;applyBrand()\"></div>\n          <div style=\"display:flex;gap:12px;margin-top:20px;flex-wrap:wrap;align-items:center\">\n            <button class=\"btn btn-primary\" onclick=\"publishSite()\">🚀 Yayınla</button>\n            <span style=\"font-size:12.5px;color:#888\">Kaydedilir ve neden-biz dâhil tüm sayfalara uygulanır.</span>\n          </div>\n        </div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-menutext\">\n        <h2>Menü & Footer Yazıları</h2><div class=\"crumb\">Üst menü, mobil menü ve footer yazıları — değiştir, canlı görün, \"Yayınla\" ile tüm sayfalara (neden-biz dâhil) uygula.</div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">Üst Menü</h3>\n          <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px 12px\">\n            <div><label>Hizmetler</label><input id=\"m_hizmetler\" oninput=\"MENU.hizmetler=this.value;applyMenuText()\"></div>\n            <div><label>Neden ? Biz (? vurgulu kalır)</label><input id=\"m_nedenBiz\" oninput=\"MENU.nedenBiz=this.value;applyMenuText()\"></div>\n            <div><label>Projeler</label><input id=\"m_projeler\" oninput=\"MENU.projeler=this.value;applyMenuText()\"></div>\n            <div><label>Bölge Zekası</label><input id=\"m_bolge\" oninput=\"MENU.bolge=this.value;applyMenuText()\"></div>\n            <div><label>Giriş</label><input id=\"m_giris\" oninput=\"MENU.giris=this.value;applyMenuText()\"></div>\n            <div><label>Teklif butonu</label><input id=\"m_teklif\" oninput=\"MENU.teklif=this.value;applyMenuText()\"></div>\n          </div>\n        </div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">Footer (Alt Menü)</h3>\n          <label>Marka açıklaması</label><textarea id=\"fo_desc\" rows=\"2\" oninput=\"FOOT.desc=this.value;applyMenuText()\"></textarea>\n          <div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px\">\n            <div><label>Kolon 1 başlığı</label><input id=\"fo_k\" oninput=\"FOOT.colKurumsal=this.value;applyMenuText()\"></div>\n            <div><label>Kolon 2 başlığı</label><input id=\"fo_h\" oninput=\"FOOT.colHizmetler=this.value;applyMenuText()\"></div>\n            <div><label>Kolon 3 başlığı</label><input id=\"fo_i\" oninput=\"FOOT.colIletisim=this.value;applyMenuText()\"></div>\n          </div>\n          <label>Adres (satır için &lt;br&gt; kullanın)</label><input id=\"fo_adres\" oninput=\"FOOT.adres=this.value;applyMenuText()\">\n          <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px\">\n            <div><label>Telefon</label><input id=\"fo_tel\" oninput=\"FOOT.tel=this.value;applyMenuText()\"></div>\n            <div><label>E-posta</label><input id=\"fo_email\" oninput=\"FOOT.email=this.value;applyMenuText()\"></div>\n          </div>\n          <label>Telif metni (copyright)</label><input id=\"fo_copy\" oninput=\"FOOT.copyright=this.value;applyMenuText()\">\n          <div style=\"margin-top:18px\"><button class=\"btn btn-primary\" onclick=\"publishSite()\">🚀 Yayınla</button></div>\n        </div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-ads\">\n        <h2>Google & Reklam</h2><div class=\"crumb\">Google Analytics, Search Console ve reklam/izleme kodları — \"Yayınla\" ile tüm sayfalara uygulanır.</div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">Google</h3>\n          <label>Google Analytics ID (G-XXXX)</label><input id=\"ad_ga\" placeholder=\"G-XXXXXXXXXX\" oninput=\"SETTINGS.googleAnalytics=this.value\">\n          <label>Google Search Console doğrulama</label><input id=\"ad_gsv\" placeholder=\"google-site-verification içeriği\" oninput=\"SETTINGS.googleSiteVerif=this.value\">\n          <div style=\"font-size:12px;color:#888;margin-top:6px\">Yayınlayınca sayfaya gtag.js ve doğrulama meta etiketi otomatik eklenir.</div>\n        </div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">Reklam / İzleme Kodu (kod yazmadan yapıştırın)</h3>\n          <label>&lt;head&gt; kodu — AdSense yükleyici, Google Tag Manager, piksel vb.</label>\n          <textarea id=\"ads_head\" rows=\"4\" placeholder=\"&lt;script async src=&quot;https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-XXXX&quot; crossorigin=&quot;anonymous&quot;&gt;&lt;/script&gt;\" oninput=\"ADS.head=this.value\"></textarea>\n          <label>Sayfa içi reklam / kod (body)</label>\n          <textarea id=\"ads_body\" rows=\"4\" placeholder=\"&lt;ins class=&quot;adsbygoogle&quot; ...&gt;&lt;/ins&gt;\" oninput=\"ADS.body=this.value\"></textarea>\n          <div style=\"font-size:12px;color:#888;margin-top:6px\">⚠ Buraya yapıştırılan &lt;script&gt; kodları sayfada çalıştırılır — yalnızca güvendiğiniz kaynakları ekleyin.</div>\n        </div>\n        <div><button class=\"btn btn-primary\" onclick=\"publishAds()\">🚀 Yayınla</button></div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-diller\">\n        <h2>Diller & İçerik (TR / EN)</h2><div class=\"crumb\">Ana sayfadaki her başlık ve paragraf otomatik listelenir. Türkçesini düzenleyin, İngilizcesini girin — üstteki TR/EN düğmesiyle önizleyin, \"Yayınla\" ile kaydedin.</div>\n        <div class=\"panelcard\">\n          <div id=\"dillerList\"></div>\n          <button class=\"btn btn-primary\" style=\"margin-top:14px\" onclick=\"publishSite()\">🚀 Yayınla</button>\n        </div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-iletisim\">\n        <h2>İletişim Sayfası & Konum</h2><div class=\"crumb\">İletişim sayfasındaki harita konumu, iletişim bilgileri ve yasal şirket künyesi. Kaydedince sayfaya anında yansır.</div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">📍 Harita Konumu</h3>\n          <div style=\"font-size:12px;color:#9fb0cc;margin-bottom:10px;line-height:1.5\">Haritaya <b>tıklayarak</b> firmanızın konumunu seçin — işaretçiyi sürükleyerek de taşıyabilirsiniz. Seçtiğiniz nokta <b>hem ana sayfada hem iletişim sayfasında</b> haritada görünür ve adres otomatik doldurulur. API anahtarı gerekmez.</div>\n          <div id=\"il_pickmap\" style=\"height:320px;border-radius:12px;overflow:hidden;border:1px solid var(--line);background:#0d1420;position:relative;z-index:0\"><div id=\"il_pickmap_ph\" style=\"position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#8fa0bb;font-size:13px;text-align:center;padding:16px\">🗺️ Harita yükleniyor…</div></div>\n          <div id=\"il_pickinfo\" style=\"font-size:12px;color:#9fb0cc;margin-top:8px;min-height:16px\"></div>\n          <div class=\"fld2\" style=\"margin-top:12px;align-items:end\">\n            <div class=\"field\" style=\"margin:0\"><label>Konum — adres ya da \"enlem,boylam\"</label><input id=\"il_mapq\" placeholder=\"Levent Mah., Beşiktaş, İstanbul\"></div>\n            <div style=\"display:flex;gap:8px;flex-wrap:wrap\"><button class=\"btn-mini\" onclick=\"ilMapSearch()\">🔎 Adresten bul</button></div>\n          </div>\n        </div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">İletişim Bilgileri</h3>\n          <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px\"><div><label>Adres</label><input id=\"il_adres\"></div><div><label>Telefon</label><input id=\"il_tel\"></div></div>\n          <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px\"><div><label>E-posta</label><input id=\"il_email\"></div><div><label>WhatsApp No</label><input id=\"il_wa\" placeholder=\"905001234567\"></div></div>\n          <label>Çalışma Saatleri</label><input id=\"il_calisma\">\n        </div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">Yasal Künye (Türk Ticaret Kanunu)</h3>\n          <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px\"><div><label>Ünvan</label><input id=\"il_unvan\"></div><div><label>Yetkili</label><input id=\"il_yetkili\"></div></div>\n          <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px\"><div><label>Vergi Dairesi</label><input id=\"il_vd\"></div><div><label>Vergi No</label><input id=\"il_vno\"></div></div>\n          <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px\"><div><label>MERSİS No</label><input id=\"il_mersis\"></div><div><label>Ticaret Sicil No</label><input id=\"il_tsicil\"></div></div>\n          <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px\"><div><label>Ticaret Odası</label><input id=\"il_oda\"></div><div><label>KEP Adresi</label><input id=\"il_kep\"></div></div>\n          <div style=\"margin-top:16px\"><button class=\"btn btn-primary\" onclick=\"saveIletisimInfo()\">🚀 Kaydet & Yayınla</button></div>\n        </div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-faq\">\n        <h2>❓ İnşaat Soru-Cevap (S.S.S.)</h2><div class=\"crumb\">Google'dan organik ziyaretçi çeken inşaat rehberi. Soru ekleyin, düzenleyin, silin. \"Kaydet & Yayınla\" ile siteye ve arama motoru yapısal verisine (FAQ Schema) anında yansır.</div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">➕ Yeni Soru Ekle</h3>\n          <label>Kategori</label><select id=\"faqNewCat\"></select>\n          <label>Soru</label><input id=\"faqNewQ\" placeholder=\"ör: Villa yaptırmak ne kadar sürer?\">\n          <label>Cevap <span style=\"color:#888;font-weight:400\">(HTML: &lt;b&gt; &lt;ul&gt; &lt;li&gt; &lt;br&gt;)</span></label><textarea id=\"faqNewA\" style=\"min-height:90px\"></textarea>\n          <div style=\"margin-top:12px\"><button class=\"btn btn-primary\" onclick=\"faqAdd()\">+ Soruyu Ekle</button></div>\n        </div>\n        <div class=\"panelcard\">\n          <div class=\"fadm-bar\">\n            <input id=\"faqAdminSearch\" type=\"search\" placeholder=\"🔍 Soru ara...\" oninput=\"renderFaqAdmin()\">\n            <select id=\"faqAdminCat\" onchange=\"renderFaqAdmin()\"></select>\n            <span class=\"fadm-count\" id=\"faqAdminCount\">0</span>\n            <button class=\"btn btn-primary\" onclick=\"faqSaveAll()\">💾 Kaydet & Yayınla</button>\n          </div>\n          <div id=\"faqAdminList\" class=\"fadm-list\"></div>\n        </div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-social\">\n        <h2>🔗 Sosyal Medya & İlan Portalleri</h2><div class=\"crumb\">Footer'daki sosyal medya ikonları ve ilan sitesi linkleri (sahibinden · hepsiemlak · emlakjet) buradan yönetilir. Boş bırakılan ikon sitede otomatik gizlenir. \"Kaydet & Uygula\" tüm sayfalara yansır.</div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">Sosyal Medya Hesapları</h3>\n          <div class=\"soc-grid\">\n            <div><label>Facebook</label><input id=\"soc_facebook\" placeholder=\"https://facebook.com/meridyenyapi\"></div>\n            <div><label>Instagram</label><input id=\"soc_instagram\" placeholder=\"https://instagram.com/meridyenyapi\"></div>\n            <div><label>X (Twitter)</label><input id=\"soc_x\" placeholder=\"https://x.com/meridyenyapi\"></div>\n            <div><label>LinkedIn</label><input id=\"soc_linkedin\" placeholder=\"https://linkedin.com/company/meridyenyapi\"></div>\n            <div><label>YouTube</label><input id=\"soc_youtube\" placeholder=\"https://youtube.com/@meridyenyapi\"></div>\n            <div><label>NEXT Sosyal</label><input id=\"soc_nsosyal\" placeholder=\"https://nsosyal.com/meridyenyapi\"></div>\n          </div>\n        </div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">İlan Portalleri</h3>\n          <div class=\"soc-grid\">\n            <div><label>sahibinden.com</label><input id=\"soc_sahibinden\" placeholder=\"https://sahibinden.com/magaza/...\"></div>\n            <div><label>hepsiemlak</label><input id=\"soc_hepsiemlak\" placeholder=\"https://hepsiemlak.com/emlak-ofisi/...\"></div>\n            <div><label>emlakjet</label><input id=\"soc_emlakjet\" placeholder=\"https://emlakjet.com/emlak-ofisi/...\"></div>\n          </div>\n          <div style=\"margin-top:16px\"><button class=\"btn btn-primary\" onclick=\"saveSocial()\">🚀 Kaydet & Uygula</button></div>\n        </div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-stats\">\n        <h2>📊 İstatistikler & Sertifikalar</h2><div class=\"crumb\">Ana sayfa ve Hizmetler sayfasındaki kurumsal rakamlar + standart/sertifika rozetleri. Rakamı sade sayı girin; site otomatik biçimlendirir (8400 → 8.400+, 2100000 → 2,1M m²). \"Kaydet & Uygula\" tüm sayfalara yansır.</div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">Kurumsal Rakamlar</h3>\n          <div class=\"soc-grid\">\n            <div><label>Yıllık Tecrübe</label><input id=\"st_yil\" type=\"number\" min=\"0\"></div>\n            <div><label>Teslim Edilen Konut</label><input id=\"st_konut\" type=\"number\" min=\"0\"></div>\n            <div><label>Tamamlanan Proje</label><input id=\"st_proje\" type=\"number\" min=\"0\"></div>\n            <div><label>Aktif Şantiye</label><input id=\"st_santiye\" type=\"number\" min=\"0\"></div>\n            <div><label>Toplam İnşa Alanı (m²)</label><input id=\"st_alan\" type=\"number\" min=\"0\"></div>\n          </div>\n        </div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin-top:0\">Standartlar & Sertifikalar</h3>\n          <label>Her satıra bir rozet yazın</label>\n          <textarea id=\"st_certs\" style=\"min-height:130px\" placeholder=\"TBDY 2018&#10;ISO 9001 · 14001 · 45001&#10;BIM Koordinasyon\"></textarea>\n          <div style=\"margin-top:16px\"><button class=\"btn btn-primary\" onclick=\"saveStats()\">🚀 Kaydet & Uygula</button></div>\n        </div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-projects\">\n        <h2>Projeler</h2><div class=\"crumb\">Projeleri ekleyin, düzenleyin veya silin · değişiklikler otomatik kaydedilir, ana sayfaya anında yansır</div>\n        <div class=\"adm-toolbar\">\n          <button class=\"btn-mini\" onclick=\"exportData()\">⬇ Tüm Veriyi Yedekle (JSON)</button>\n          <button class=\"btn-mini\" onclick=\"document.getElementById('importFile').click()\">⬆ Yedekten Geri Yükle</button>\n          <input type=\"file\" id=\"importFile\" accept=\"application/json\" style=\"display:none\" onchange=\"importData(this)\">\n        </div>\n        <div class=\"panelcard\"><div id=\"admPjList\"></div>\n          <button class=\"miniadd\" onclick=\"admAddProject()\">+ Yeni Proje Ekle</button></div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-services\">\n        <h2>Hizmetler</h2><div class=\"crumb\">Hizmet kartlarını yönetin</div>\n        <div class=\"panelcard\"><div id=\"admSvcList\"></div>\n          <button class=\"miniadd\" onclick=\"admAddSvc()\">+ Yeni Hizmet Ekle</button></div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-leads\">\n        <h2>Müşteriler / Teklif Talepleri</h2><div class=\"crumb\">Siteden gelen teklif ve iletişim talepleri</div>\n        <div class=\"panelcard\"><table class=\"adm-tbl\"><thead><tr><th>Ad Soyad</th><th>Telefon</th><th>Konu</th><th>Kaynak</th><th>Tarih</th></tr></thead>\n          <tbody id=\"leadsBody\"></tbody></table><div id=\"leadsEmpty\" style=\"color:var(--muted);font-size:14px;padding:14px 4px\">Henüz teklif talebi yok. Sitedeki formdan gelen talepler burada listelenir.</div></div>\n      </div>\n      <!-- GÖRÜŞMELER & TEKLİFLER (ProX Asistan + üye teklifleri) -->\n      <div class=\"adm-pane\" id=\"pane-gorusmeler\">\n        <h2>Görüşmeler & Teklifler</h2>\n        <div class=\"crumb\">Site kullanıcılarının ProX Asistan yapay zekâ görüşmeleri, teklif talepleri ve üye kayıtları — yetkili olarak tam ve detaylı takip edin, geri arama taleplerini yönetin.</div>\n        <div class=\"adm-toolbar\"><button class=\"btn-mini\" onclick=\"renderGorusmeler()\">↻ Yenile</button></div>\n        <div id=\"gorusmelerBody\"></div>\n      </div>\n      <!-- ARSA & BAĞIMSIZ BÖLÜM YÖNETİMİ -->\n      <div class=\"adm-pane\" id=\"pane-arsa\">\n        <h2>Kat Karşılığı Hesaplama & Fizibilite</h2>\n        <div class=\"crumb\">Arsa m² + imar durumu girin → tahmini daire adedi, arsa sahibi/müteahhit paylaşımı, satış geliri ve net kâr otomatik hesaplansın.</div>\n        <div class=\"adm-toolbar\">\n          <button class=\"btn-mini\" onclick=\"admAddArsa()\">+ Yeni Fizibilite Hesabı</button>\n        </div>\n        <div id=\"arsaList\"></div>\n      </div>\n      <!-- İLANLAR (EİDS üzerinden yayın) -->\n      <div class=\"adm-pane\" id=\"pane-ilanlar\">\n        <h2>İlanlar</h2>\n        <div class=\"crumb\">Kendi taşınmazlarınızı bağımsız ilan olarak yayınlayın. Her ilan <b>T.C. Ticaret Bakanlığı EİDS</b> (Elektronik İlan Doğrulama Sistemi) kapsamında yetki durumu takip edilir; resmî doğrulama yetkili EİDS/TTBS bağlantısı üzerinden yapılır.<!-- HONESTY (P0-10): \"üzerinden doğrulanır\" + doğrulanmamış tarih iddiası → durum-takibi. --></div>\n        <div class=\"panelcard ins-eids-bar\">\n          <div class=\"ins-eids-belge\"><label>Taşınmaz Ticareti Yetki Belgesi No <span class=\"ins-req\">(kurumsal)</span></label><input id=\"insEidsYetkiBelge\" placeholder=\"Emlak işletmesi yetki belge no\" oninput=\"insEidsSetBelge(this.value)\"></div>\n          <div class=\"ins-note\">🛡️ Doğrulama, NADAS sunucusu (ProX / emlakekspertizi.com) üzerinden Ticaret Bakanlığı EİDS sistemine yapılır. <b>Kod uydurulmaz.</b> Canlı EİDS bağlantısı devrede değilken ilanlar dürüstçe <b>“Doğrulama Bekliyor”</b> durumunda kalır. Doğrulanan ilan yeşil <b>EİDS Doğrulandı</b> rozetiyle görünür.</div>\n        </div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin:0 0 6px\">📤 Toplu İlan Aktar</h3>\n          <div class=\"crumb\" style=\"margin:0 0 10px\">Excel / Google Sheets’ten satırları kopyalayıp aşağıya yapıştırın (sütun ayracı sekme, <b>;</b> veya <b>,</b> — otomatik algılanır). Sıra: <b>Başlık · İşlem · Tip · İl · İlçe · Mahalle · m² · Oda · Kat · Fiyat · Açıklama</b>. Yalnız <b>size ait</b> ilanlar — portal izinsiz taraması yapılmaz.</div>\n          <textarea id=\"insBulk_in\" rows=\"5\" style=\"width:100%;box-sizing:border-box;font-family:ui-monospace,Menlo,monospace;font-size:12px\" placeholder=\"Levent Rezidans 2+1&#9;Satılık&#9;Daire&#9;İstanbul&#9;Beşiktaş&#9;Levent&#9;112&#9;2+1&#9;14&#9;14750000&#9;Açıklama…\"></textarea>\n          <div class=\"adm-toolbar\" style=\"margin-top:8px\">\n            <button class=\"btn-mini\" onclick=\"insBulkSample()\">Örnek Doldur</button>\n            <button class=\"btn-mini\" onclick=\"insBulkPreview()\">👁 Önizle</button>\n            <button class=\"btn-mini\" style=\"background:var(--accent);color:#fff\" onclick=\"insBulkImport()\">📥 İçe Aktar</button>\n          </div>\n          <div id=\"insBulk_out\" style=\"margin-top:8px\"></div>\n        </div>\n        <div class=\"adm-toolbar\"><button class=\"btn-mini\" onclick=\"insIlanAdd()\">+ Yeni İlan Ekle</button></div>\n        <div class=\"panelcard\"><div id=\"insIlanList\"></div></div>\n      </div>\n      <!-- ÖZEL PORTFÖY (ProX destekli üretim · EİDS hariç) -->\n      <div class=\"adm-pane\" id=\"pane-portfoy\">\n        <h2>Özel Portföy</h2>\n        <div class=\"crumb\">Off-market / kapalı portföy. Kayıtlar <b>ProX bölge verisinden üretilir</b> (pazar tahmini) — kamuya açık EİDS ilanı değildir, bu yüzden <b>EİDS kapsamı dışındadır</b>. Fiyatlar ProX endeks/analiz tahminidir, kesin ilan fiyatı değildir.</div>\n        <div class=\"adm-toolbar\">\n          <button class=\"btn-mini\" id=\"insOzGenBtn\" style=\"background:var(--accent);color:#fff\" onclick=\"insOzelGen()\">⚡ ProX ile Portföy Üret</button>\n        </div>\n        <div class=\"panelcard\"><div id=\"insOzelList\"></div></div>\n      </div>\n      <!-- 3D PROJE ÜRETİCİ & FİZİBİLİTE RAPORU -->\n      <div class=\"adm-pane\" id=\"pane-proje3d\">\n        <h2>3D Proje Üretici & Fizibilite Raporu</h2>\n        <div class=\"crumb\">Müşterinizin arsasını girin → 3D model + dükkan/daire dağılımı + kat karşılığı pay paylaşımı + arsa payına kadar detaylı rapor → 4 görsel & not ekleyin → PDF indirin / gönderin.</div>\n        <div class=\"p3d-layout\">\n          <div class=\"p3d-controls\">\n            <div class=\"panelcard\">\n              <h3 style=\"margin:0 0 12px\">👤 Müşteri & Arsa Bilgileri</h3>\n              <label>Müşteri Adı Soyadı</label><input type=\"text\" id=\"p3_musteri\" value=\"\" placeholder=\"Örn. Mehmet Yılmaz\" oninput=\"updateProje3D()\">\n              <label>Proje / Arsa Adı</label><input type=\"text\" id=\"p3_ad\" value=\"Müşteri Arsası\" oninput=\"updateProje3D()\">\n              <div class=\"ed3\">\n                <div><label>İl</label><input type=\"text\" id=\"p3_il\" value=\"İstanbul\" oninput=\"updateProje3D()\"></div>\n                <div><label>İlçe</label><input type=\"text\" id=\"p3_ilce\" value=\"\" oninput=\"updateProje3D()\"></div>\n                <div><label>Mahalle</label><input type=\"text\" id=\"p3_mah\" value=\"\" oninput=\"updateProje3D()\"></div>\n              </div>\n              <div class=\"ed2\">\n                <div><label>Ada</label><input type=\"text\" id=\"p3_ada\" value=\"\" placeholder=\"Örn. 1234\" oninput=\"updateProje3D()\"></div>\n                <div><label>Parsel</label><input type=\"text\" id=\"p3_parsel\" value=\"\" placeholder=\"Örn. 56\" oninput=\"updateProje3D()\"></div>\n              </div>\n            </div>\n            <div class=\"panelcard\" style=\"margin-top:14px\">\n              <h3 style=\"margin:0 0 12px\">📐 İmar & Yapı</h3>\n              <label>Arsa m²</label><input type=\"number\" id=\"p3_m2\" value=\"1500\" oninput=\"updateProje3D()\">\n              <div class=\"ed2\">\n                <div><label>Emsal (KAKS)</label><input type=\"number\" step=\"0.01\" id=\"p3_emsal\" value=\"2.0\" oninput=\"updateProje3D()\"></div>\n                <div><label>TAKS</label><input type=\"number\" step=\"0.01\" id=\"p3_taks\" value=\"0.40\" oninput=\"updateProje3D()\"></div>\n              </div>\n              <div class=\"ed2\">\n                <div><label>Kat Adedi</label><input type=\"number\" id=\"p3_kat\" value=\"6\" oninput=\"updateProje3D()\"></div>\n                <div><label>Blok Sayısı</label><input type=\"number\" id=\"p3_blok\" value=\"2\" min=\"1\" max=\"6\" oninput=\"updateProje3D()\"></div>\n              </div>\n              <label>Bina Tipi</label>\n              <select id=\"p3_tip\" onchange=\"updateProje3D()\">\n                <option value=\"konut\">Konut (Apartman)</option>\n                <option value=\"rezidans\">Rezidans (Yüksek Kat)</option>\n                <option value=\"villa\">Villa Sitesi</option>\n                <option value=\"ticari\">Ticari / Karma</option>\n              </select>\n            </div>\n            <div class=\"panelcard\" style=\"margin-top:14px;border:1px solid var(--accent)\">\n              <h3 style=\"margin:0 0 8px\">🏛️ Gerçek Mimari Proje (GLB/glTF)</h3>\n              <p style=\"font-size:12px;color:var(--muted);margin:0 0 10px;line-height:1.5\">Mimarınızın 3D modelini (Revit/ArchiCAD/SketchUp/Lumion → <b>.glb</b> export) yükleyin. Müşteriye gerçek projeyi 3D olarak gösterin. Konsept kütle yerine gerçek model görünür.</p>\n              <input type=\"file\" id=\"glbInput\" accept=\".glb,.gltf\" style=\"display:none\" onchange=\"loadGLBModel(this)\">\n              <button class=\"btn-mini\" style=\"width:100%\" onclick=\"document.getElementById('glbInput').click()\">📤 Mimari Model Yükle (.glb)</button>\n              <div id=\"glbStatus\" style=\"font-size:12px;margin-top:8px;color:var(--muted)\"></div>\n              <button class=\"btn-mini\" id=\"glbClearBtn\" style=\"width:100%;margin-top:8px;display:none\" onclick=\"clearGLBModel()\">🗑️ Modeli Kaldır (konsepte dön)</button>\n            </div>\n            <div class=\"panelcard\" style=\"margin-top:14px\">\n              <h3 style=\"margin:0 0 12px\">🏬 Bağımsız Bölüm Dağılımı</h3>\n              <div class=\"ed2\">\n                <div><label>Zemin Dükkan Sayısı</label><input type=\"number\" id=\"p3_dukkan\" value=\"4\" min=\"0\" oninput=\"updateProje3D()\"></div>\n                <div><label>Ort. Dükkan m²</label><input type=\"number\" id=\"p3_dukkanM2\" value=\"60\" oninput=\"updateProje3D()\"></div>\n              </div>\n              <div class=\"ed2\">\n                <div><label>Ort. Daire m²</label><input type=\"number\" id=\"p3_daireM2\" value=\"115\" oninput=\"updateProje3D()\"></div>\n                <div><label>Daire/Kat (blok başı)</label><input type=\"number\" id=\"p3_daireKat\" value=\"4\" oninput=\"updateProje3D()\"></div>\n              </div>\n            </div>\n            <div class=\"panelcard\" style=\"margin-top:14px\">\n              <h3 style=\"margin:0 0 12px\">🤝 Kat Karşılığı Paylaşımı</h3>\n              <div class=\"ed2\">\n                <div><label>Arsa Sahibi Payı %</label><input type=\"number\" id=\"p3_payArsa\" value=\"45\" oninput=\"updateProje3D()\"></div>\n                <div><label>Müteahhit Payı %</label><input type=\"number\" id=\"p3_payMut\" value=\"55\" readonly style=\"opacity:.7\"></div>\n              </div>\n              <div class=\"ed2\">\n                <div><label>Daire Satış ₺/m²</label><input type=\"number\" id=\"p3_satisM2\" value=\"75000\" oninput=\"updateProje3D()\"></div>\n                <div><label>İnşaat ₺/m² Maliyet</label><input type=\"number\" id=\"p3_maliyetM2\" value=\"18000\" oninput=\"updateProje3D()\"></div>\n              </div>\n            </div>\n            <div class=\"panelcard\" style=\"margin-top:14px\">\n              <h3 style=\"margin:0 0 12px\">🖼️ Rapor Görselleri (max 4)</h3>\n              <div class=\"p3img-grid\" id=\"p3imgGrid\"></div>\n              <input type=\"file\" id=\"p3imgInput\" accept=\"image/*\" style=\"display:none\" onchange=\"addReportImage(this)\">\n              <button class=\"btn-mini\" style=\"margin-top:8px;width:100%\" onclick=\"document.getElementById('p3imgInput').click()\">+ Görsel Ekle</button>\n            </div>\n            <div class=\"panelcard\" style=\"margin-top:14px\">\n              <h3 style=\"margin:0 0 12px\">📝 Rapor Notu</h3>\n              <textarea class=\"adm-ta\" rows=\"3\" id=\"p3_not\" placeholder=\"Müşteriye özel notlar, öneriler, açıklamalar...\" oninput=\"saveP3Note()\"></textarea>\n            </div>\n            <button class=\"btn-mini\" data-feature=\"canUsePdfReports\" style=\"margin-top:14px;width:100%;background:var(--accent);color:#0e0f13;border-color:var(--accent);font-weight:700\" onclick=\"generateReport()\">📄 Fizibilite Raporu Oluştur (PDF)</button>\n            <button class=\"btn-mini\" style=\"margin-top:8px;width:100%\" onclick=\"sendProje3DWhatsApp()\">📱 Özeti WhatsApp'tan Gönder</button>\n            <button class=\"btn-mini\" style=\"margin-top:8px;width:100%\" onclick=\"showKatPlani()\">📐 Kat Planı Oluştur (m² · daire/dükkan)</button>\n            <button class=\"btn-mini\" style=\"margin-top:8px;width:100%\" onclick=\"captureProje3D()\">📸 3D Görüntüyü İndir (PNG)</button>\n          </div>\n          <div class=\"p3d-right\">\n            <div class=\"p3d-stage\">\n              <canvas id=\"adminBuild3d\"></canvas>\n              <div class=\"p3d-hint\">🖱️ Döndür · tekerlek ile yakınlaştır</div>\n            </div>\n            <div class=\"panelcard\" style=\"margin-top:14px\">\n              <h3 style=\"margin:0 0 10px\">📊 Anlık Fizibilite Özeti</h3>\n              <div id=\"p3_stats\"></div>\n            </div>\n          </div>\n        </div>\n      </div>\n      <!-- DWG MİMARİ PROJE -->\n      <div class=\"adm-pane\" id=\"pane-dwgproje\">\n        <h2>📐 DWG Mimari Proje → Projeler</h2>\n        <div class=\"crumb\">Mimarın <b>.dwg</b> dosyasını yükleyin → çizim <b>eksiksiz okunur</b> (2B gerçek vektör plan) → <b>Pro<span style=\"background:#16a34a;color:#07130a;border-radius:4px;padding:0 5px;font-weight:800\">X</span></b> dosyanın <b>Alan Cetvelinden</b> gerçek verileri (kat · bağımsız bölüm · toplam inşaat alanı · m²) okur — <b>hiçbir şey uydurmaz</b> + <b>gerçek kat planları görsele</b> çevrilir (her kat ayrı) → <b>Projeler</b> sayfasına kaydedilir. Daire tipleri/fiyatlar admin panelde tamamlanır.</div>\n        <div class=\"p3d-layout\">\n          <div class=\"p3d-controls\">\n            <div class=\"panelcard\">\n              <h3 style=\"margin:0 0 12px\">🏷️ Proje Bilgileri</h3>\n              <label>Proje Adı</label><input type=\"text\" id=\"dwg_ad\" placeholder=\"Örn. Fatih Menteşe Konutları\">\n              <div class=\"ed3\">\n                <div><label>İl</label><input type=\"text\" id=\"dwg_il\" value=\"İstanbul\"></div>\n                <div><label>İlçe</label><input type=\"text\" id=\"dwg_ilce\" value=\"\" placeholder=\"Örn. Kadıköy\"></div>\n                <div><label>Mahalle</label><input type=\"text\" id=\"dwg_mah\" value=\"\"></div>\n              </div>\n              <div class=\"ed2\">\n                <div><label>Ada</label><input type=\"text\" id=\"dwg_ada\" value=\"\" placeholder=\"Örn. 1234\"></div>\n                <div><label>Parsel</label><input type=\"text\" id=\"dwg_parsel\" value=\"\" placeholder=\"Örn. 56\"></div>\n              </div>\n            </div>\n            <div class=\"panelcard\" style=\"margin-top:14px;border:1px solid var(--accent)\">\n              <h3 style=\"margin:0 0 8px\">📤 Mimari Proje Yükle</h3>\n              <p style=\"font-size:12px;color:var(--muted);margin:0 0 10px;line-height:1.5\"><b>.dwg</b> (veya .dxf) seçin → <b>Yapıyı Otomatik Çöz</b> ile kat/mahal/m² + 2B plan çıkar. (libredwg-web · WASM · arayüz donmaz)</p>\n              <input type=\"file\" id=\"apsFile\" accept=\".dwg,.dxf\" style=\"display:none\" onchange=\"if(this.files[0])window.dwgLocalPreview(this.files[0]);this.value=''\">\n              <button class=\"btn-mini\" style=\"width:100%;background:var(--accent);color:#0e0f13;border-color:var(--accent);font-weight:700\" onclick=\"document.getElementById('apsFile').click()\">📤 .dwg / .dxf Seç</button>\n              <div id=\"apsStatus\" style=\"font-size:12px;margin-top:8px;color:var(--muted);line-height:1.45\"></div>\n              <div id=\"apsPreview\" style=\"margin-top:8px\"></div>\n              <button class=\"btn-mini\" id=\"apsBackBtn\" style=\"width:100%;margin-top:8px;display:none\" onclick=\"apsCloseViewer()\">← Planı Kapat</button>\n            </div>\n          </div>\n          <div class=\"p3d-right\">\n            <div id=\"apsViewerWrap\" style=\"display:none\">\n              <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:8px\">\n                <b style=\"font-family:var(--head)\">📐 Gerçek Vektör Kat Planı (.dwg)</b>\n                <button class=\"btn-mini\" onclick=\"apsCloseViewer()\" style=\"width:auto\">✕ Kapat</button>\n              </div>\n              <div id=\"apsViewer\" style=\"position:relative;width:100%;height:560px;background:#0b0d12;border:1px solid var(--line);border-radius:12px;overflow:hidden\"></div>\n              <p style=\"font-size:11.5px;color:var(--muted);margin:8px 0 0\">Gerçek vektör kat planı. Sağ üstteki <b>＋ / －</b> ile yakınlaştırıp kaydırarak inceleyin.</p>\n            </div>\n            <div id=\"dwgAnalyz\"></div>\n            <div id=\"dwgFloorPlans\"></div>\n            <div id=\"dwgAiResult\"></div>\n            <div class=\"panelcard\" id=\"dwgHint\" style=\"margin-top:14px\">\n              <p style=\"font-size:12.5px;color:var(--muted);margin:0;line-height:1.6\">💡 <b>1)</b> Soldan bir <b>.dwg</b> yükleyip <b>🏗️ Yapıyı Otomatik Çöz</b>'e basın (2B plan açılır). <b>2)</b> <b>Pro<span style=\"background:#16a34a;color:#07130a;border-radius:3px;padding:0 4px;font-weight:800\">X</span> ile Çözümle</b> ile Alan Cetvelinden gerçek veriler okunur (uydurma yok). <b>3)</b> <b>Portföye Ekle</b> ile kaydedin; daire tipi/fiyat admin panelde tamamlanır. Büyük dosyalar Web Worker'da işlenir (arayüz donmaz); ilk seferde ~9 MB motor iner.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n      <!-- SÖZLEŞMELER -->\n      <div class=\"adm-pane\" id=\"pane-contracts\">\n        <h2>Sözleşmeler</h2>\n        <div class=\"crumb\">İnşaat, kat karşılığı ve taşeron sözleşmelerini tek yerden yönetin.</div>\n        <div class=\"adm-toolbar\">\n          <button class=\"btn-mini\" onclick=\"admAddContract('insaat')\">+ İnşaat Sözleşmesi</button>\n          <button class=\"btn-mini\" onclick=\"admAddContract('kat-karsiligi')\">+ Kat Karşılığı Sözleşmesi</button>\n          <button class=\"btn-mini\" onclick=\"admAddContract('taseron')\">+ Taşeron Sözleşmesi</button>\n        </div>\n        <div id=\"contractList\"></div>\n      </div>\n      <!-- AYARLAR -->\n      <div class=\"adm-pane\" id=\"pane-settings\">\n        <h2>Ayarlar & Güvenlik</h2>\n        <div class=\"crumb\">Yönetici şifresi, Google entegrasyonları ve site meta ayarları.</div>\n        <div class=\"panelcard\">\n          <h3 style=\"margin:0 0 14px\">🔐 Yönetici Girişi</h3>\n          <div class=\"ed2\">\n            <div><label>Kullanıcı Adı</label><input type=\"text\" id=\"set_user\"></div>\n            <div><label>Mevcut Şifre (doğrulama)</label><input type=\"password\" id=\"set_curpass\" placeholder=\"Mevcut şifreniz\"></div>\n          </div>\n          <div class=\"ed2\">\n            <div><label>Yeni Şifre</label><input type=\"password\" id=\"set_newpass\" placeholder=\"Yeni şifre\"></div>\n            <div><label>Yeni Şifre (tekrar)</label><input type=\"password\" id=\"set_newpass2\" placeholder=\"Tekrar\"></div>\n          </div>\n          <button class=\"btn-mini\" style=\"margin-top:12px\" onclick=\"changePassword()\">🔑 Şifreyi Değiştir</button>\n          <div id=\"passMsg\" style=\"margin-top:8px;font-size:13px\"></div>\n        </div>\n        <div class=\"panelcard\" style=\"margin-top:16px\">\n          <h3 style=\"margin:0 0 14px\">🏢 Firma Bilgileri (sözleşmelerde otomatik kullanılır)</h3>\n          <div class=\"ed2\">\n            <div><label>Firma Ünvanı</label><input type=\"text\" id=\"set_funvan\"></div>\n            <div><label>Vergi No</label><input type=\"text\" id=\"set_fvergi\"></div>\n          </div>\n          <div class=\"ed2\">\n            <div><label>MERSİS No</label><input type=\"text\" id=\"set_fmersis\"></div>\n            <div><label>Yetkili</label><input type=\"text\" id=\"set_fyetkili\"></div>\n          </div>\n          <label>Firma Adresi</label><input type=\"text\" id=\"set_fadres\">\n          <div class=\"ed2\">\n            <div><label>Telefon</label><input type=\"text\" id=\"set_ftel\"></div>\n            <div><label>E-posta</label><input type=\"text\" id=\"set_femail\"></div>\n          </div>\n          <button class=\"btn-mini\" style=\"margin-top:12px\" onclick=\"saveFirmaInfo()\">💾 Firma Bilgilerini Kaydet</button>\n        </div>\n        <div class=\"panelcard\" style=\"margin-top:16px\">\n          <h3 style=\"margin:0 0 14px\">🌐 Google & Entegrasyonlar</h3>\n          <label>Google Maps API Anahtarı</label><input type=\"text\" id=\"set_gmaps\" placeholder=\"AIza...\">\n          <label>Google Analytics ID (G-XXXX)</label><input type=\"text\" id=\"set_ga\" placeholder=\"G-XXXXXXX\">\n          <label>Google Search Console Doğrulama Kodu</label><input type=\"text\" id=\"set_gsv\" placeholder=\"google-site-verification içeriği\">\n          <label>reCAPTCHA Site Anahtarı</label><input type=\"text\" id=\"set_recaptcha\" placeholder=\"6Lc...\">\n          <button class=\"btn-mini\" style=\"margin-top:12px\" onclick=\"saveGoogleSettings()\">💾 Entegrasyonları Kaydet</button>\n        </div>\n        <div class=\"panelcard\" style=\"margin-top:16px\">\n          <h3 style=\"margin:0 0 14px\">🔎 SEO & Meta</h3>\n          <label>Site Başlığı (meta title)</label><input type=\"text\" id=\"set_mtitle\">\n          <label>Site Açıklaması (meta description)</label><textarea class=\"adm-ta\" rows=\"2\" id=\"set_mdesc\"></textarea>\n          <label>WhatsApp Numarası (90 ile, başında + yok)</label><input type=\"text\" id=\"set_wa\" placeholder=\"905001234567\">\n          <button class=\"btn-mini\" style=\"margin-top:12px\" onclick=\"saveSeoSettings()\">💾 SEO Ayarlarını Kaydet</button>\n        </div>\n      </div>\n      <div class=\"adm-pane\" id=\"pane-theme\">\n        <h2>Tema & Renk</h2><div class=\"crumb\">Site renk şemasını seçin · 10 hazır tema + özel renk</div>\n        <div class=\"panelcard\"><h3>Hazır Temalar</h3><div class=\"swatches\" id=\"admSwatches\"></div>\n          <label>Özel vurgu renkleri (ana / ikincil)</label>\n          <div style=\"display:flex;gap:10px;align-items:center;margin-top:6px\">\n            <input type=\"color\" id=\"a_accent\" value=\"#2563eb\" oninput=\"setVar('--accent',this.value)\" style=\"width:48px;height:40px;border:1px solid var(--line);border-radius:9px\">\n            <input type=\"color\" id=\"a_accent2\" value=\"#c8962f\" oninput=\"setVar('--accent-2',this.value)\" style=\"width:48px;height:40px;border:1px solid var(--line);border-radius:9px\">\n            <button class=\"btn btn-ghost\" style=\"border-color:var(--line);color:var(--ink);padding:8px 14px;font-size:13px\" onclick=\"applyMode('dark')\">Koyu Mod</button>\n            <button class=\"btn btn-ghost\" style=\"border-color:var(--line);color:var(--ink);padding:8px 14px;font-size:13px\" onclick=\"applyMode('light')\">Açık Mod</button>\n          </div>\n          <label style=\"margin-top:16px\">Zemin renkleri (genel / koyu şeritler / kart)</label>\n          <div style=\"display:flex;gap:10px;align-items:center;margin-top:6px\">\n            <input type=\"color\" id=\"a_bg\" value=\"#0e0f13\" oninput=\"setVar('--bg',this.value)\" title=\"Sayfa zemini\" style=\"width:48px;height:40px;border:1px solid var(--line);border-radius:9px\">\n            <input type=\"color\" id=\"a_brandc\" value=\"#0e0f13\" oninput=\"setVar('--brand',this.value)\" title=\"Koyu şeritler (istatistik / bölge)\" style=\"width:48px;height:40px;border:1px solid var(--line);border-radius:9px\">\n            <input type=\"color\" id=\"a_surface\" value=\"#181a20\" oninput=\"setVar('--surface',this.value)\" title=\"Kart zemini\" style=\"width:48px;height:40px;border:1px solid var(--line);border-radius:9px\">\n          </div>\n          <div class=\"crumb\" style=\"margin-top:8px\">Renk değiştirdiğinizde yazı renkleri okunabilirlik için otomatik ayarlanır.</div>\n        </div>\n      </div>\n    </div>\n  </div>\n";
